INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kann ich Kompatibilität ohne Tests sicherstellen?', 2, '[{"text": "Nein", "correct": true, "because": "Tests validieren Anpassung"}, {"text": "Ja", "correct": false, "because": "Ohne Tests riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit der Kompatibilitätssicherung?', 3, '[{"text": "Systemfunktionalität", "correct": true, "because": "Sichert Betrieb"}, {"text": "UI-Design", "correct": false, "because": "Anderer Fokus"}, {"text": "Marketing", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden helfen bei der Kompatibilitätssicherung?', 5, '[{"text": "Versionsprüfung", "correct": true, "because": "Testet neue Systeme"}, {"text": "Regressionstests", "correct": true, "because": "Sichert Bestand"}, {"text": "Zufälliges Raten", "correct": false, "because": "Unzuverlässig"}, {"text": "Visuelle Checks", "correct": false, "because": "Oberflächlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kompatibilität braucht Tests. b) Neue Hardware ist immer kompatibel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) nicht garantiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Kompatibilitätssicherung?', 4, '[{"text": "Systemanforderungen", "correct": false, "because": "Definiert Grenzen"}, {"text": "Testumgebung", "correct": false, "because": "Simuliert System"}, {"text": "Schriftgröße", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kompatibilität automatisch gegeben ist?', 2, '[{"text": "Nein", "correct": true, "because": "Anpassung nötig"}, {"text": "Ja", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool nutze ich für Kompatibilitätstests?', 3, '[{"text": "VirtualBox", "correct": true, "because": "Simuliert Systeme"}, {"text": "Notepad", "correct": false, "because": "Kein Testtool"}, {"text": "E-Mail", "correct": false, "because": "Unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen Kompatibilitätssicherung effektiv?', 5, '[{"text": "Testabdeckung", "correct": true, "because": "Prüft Systeme"}, {"text": "Dokumentation", "correct": true, "because": "Erklärt Anpassungen"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}, {"text": "Lange Texte", "correct": false, "because": "Ermüdend"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Neue OS-Versionen sind immer kompatibel. b) Tests sind optional. Stimmt das?', 3, '[{"text": "Beides falsch", "correct": true, "because": "a) nicht garantiert, b) nötig"}, {"text": "Beides stimmt", "correct": false, "because": "Nicht korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Kompatibilitätssicherung?', 4, '[{"text": "Testsysteme", "correct": false, "because": "Simuliert Umgebung"}, {"text": "Versionsupdates", "correct": false, "because": "Passt Software an"}, {"text": "Teamfotos", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Kompatibilität nur für Software wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Hardware zählt"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten sind für Kompatibilitätstests entscheidend?', 4, '[{"text": "Systemanforderungen", "correct": true, "because": "Definiert Grenzen"}, {"text": "Testprotokolle", "correct": true, "because": "Dokumentiert Ergebnisse"}, {"text": "UI-Design", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Kompatibilität ohne Anpassung läuft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Updates oft nötig"}, {"text": "Ja", "correct": false, "because": "Selten der Fall"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Kompatibilitätssicherung?', 3, '[{"text": "Testdurchführung", "correct": true, "because": "Validiert Funktion"}, {"text": "Schnelligkeit", "correct": false, "because": "Qualität zählt"}, {"text": "Vermutungen", "correct": false, "because": "Unzuverlässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Regressionstests prüfen Kompatibilität. b) Neue Systeme brauchen keine Anpassung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) oft falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Kompatibilitätssicherung?', 5, '[{"text": "Stabilität", "correct": true, "because": "Verhindert Abstürze"}, {"text": "Zukunftssicherheit", "correct": true, "because": "Passt an neue Systeme"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Schnelle Tests", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Kompatibilitätssicherung unwichtig?', 3, '[{"text": "Systemversionen", "correct": false, "because": "Definiert Ziel"}, {"text": "Testumgebung", "correct": false, "because": "Simuliert Realität"}, {"text": "Papierformat", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzen Tests die Anpassung?', 3, '[{"text": "Nein", "correct": true, "because": "Tests zeigen Bedarf"}, {"text": "Ja", "correct": false, "because": "Anpassung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Kompatibilität nur für OS gilt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Hardware, Treiber"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature ist für die Kompatibilitätssicherung entscheidend?', 4, '[{"text": "Testautomatisierung", "correct": true, "because": "Effizient und skalierbar"}, {"text": "Hohe Komplexität", "correct": false, "because": "Verwirrt"}, {"text": "Statische Daten", "correct": false, "because": "Nicht primär"}]');
